// And groups predicates with the AND operator between them.
func And(predicates ...predicate.HandoffRecord) predicate.HandoffRecord {
	return predicate.HandoffRecord(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.HandoffRecord) predicate.HandoffRecord {
	return predicate.HandoffRecord(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.HandoffRecord) predicate.HandoffRecord {
	return predicate.HandoffRecord(sql.NotPredicates(p))
}
